    bool preparar(int nuevaBase, int nuevoPaso);
    int consultar(int indice);
}

#endif

#include "configuracion.hpp"

namespace configuracion {
    constinit int base = 0;
    constinit int paso = 0;
    constinit bool lista = false;

    bool preparar(int nuevaBase, int nuevoPaso) {
        if (nuevaBase < 0 || nuevaBase > 9 ||
            nuevoPaso < 1 || nuevoPaso > 3) {
            return false;
        }
        const int ultimo = nuevaBase + 3 * nuevoPaso;
        if (ultimo > 15) {
            return false;
        }
        base = nuevaBase;
        paso = nuevoPaso;
        lista = true;
        return true;
    }
}

#include "configuracion.hpp"

namespace configuracion {
    int consultar(int indice) {
        if (!lista || indice < 0 || indice > 3) {
            return -1;
        }
        return base + indice * paso;
    }
}

